import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"晉","description":"高岛易断 - 晉","frontmatter":{"title":"晉","description":"高岛易断 - 晉"},"headers":[],"relativePath":"zh/classics/takashima/035.md","filePath":"zh/classics/takashima/035.md"}'),i={name:"zh/classics/takashima/035.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><h2 id="晉-1" tabindex="-1">晉 <a class="header-anchor" href="#晉-1" aria-label="Permalink to “晉”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>晋：康侯用锡马蕃庶，昼日三接。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>卦象上明下顺，《离》明为日，故象君，《坤》顺为臣，故象臣，合之为君明臣良之象。《坤》为国，为邦，故谓“侯”。《坤》为康，康安也；《坤》为马，故谓“马”；《坤》为众，故谓“蕃庶”；《离》为日，故谓“昼”。盖爻称“康侯”者，谓明臣也，明臣升进，天子美之，赐以车马蕃庶，言车马之多也。“昼日三接”者，言不特赐予之多，且觌见之频，一昼之间，三度接见也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>明出地上，《晋》，君子以自昭明德。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>日西入为夕，东出为旦。方其始出，渐进渐高，愈高愈明，光无不照，幽隐遍烛，即《晋》之象。君子法此象，以自明其德。德，心之德也，与生俱来，灵明夙具，本无一毫私欲，得而蔽掩，犹日之初出于地，沧沧凉凉，明光华照，本无一些云翳。“自昭明德”，昭，即明也，所谓自昭明德，明德而犹待于明。此事不容假贷，唯在自知之而自明之耳。君子切而责之于自，致知格物，以启自昭之端，诚意正心，以致自昭之实，谓之“君子以自昭明德”也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：正当好运新来，犹朝日初出，渐升渐高，明光普照也。吉。</p><p>○　问战征：当大军初发，顺道而进，宜日战，不宜夜攻。</p><p>○　问营商：最利煤炭地火等生业，取其明也。吉。</p><p>○　问功名：有功名指日高升之象，吉。</p><p>○　问讼事：宜返而自讼。</p><p>○　问家宅：此宅朝东南，高敞明朗，得太阳吉曜照临，大吉。</p><p>○　问六甲：生女。</p><p>○　问失物：在明堂中寻之，得。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居下卦之始，柔进上行，自初起，首曰“晋如”，若欲进而未果；继曰“摧如”，若有摧而见阻。初与四应，四不当位，不特不应，且所以摧初之进者，实四为之也。然虽见摧，惟其得贞，是以吉也。“罔孚”者，推其摧之由来，虽四为之，亦由上下之交未孚耳。《坤》为裕，故曰“裕”。当其未孚，或汲汲以干进，或悻悻而怀忿，皆所以取咎也，唯雍容宽裕，乐道自处，咎何有焉？故曰“裕无咎”。《象传》曰“独行正也”，谓摧者不正，《晋》者能独行其正耳。“无咎，未受命也”，谓其未受赐命，只宜宽裕以待之耳。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：目下好运初来，虽无灾咎，尚未盛行，宜迟缓以待之。吉。</p><p>○　问战征：初次行军，众心未定，宜宽以待之。吉。</p><p>○　问营商：货物初到，商情未洽，宜宽以时日，早则四日，迟则四月，到四爻曰“众允”，则货可旺销，必大获利。</p><p>○　问功名：功名固所自有，不可知者迟早耳，宜宽怀以俟。</p><p>○　问家宅：此宅本吉，一时未许进居，为两情未洽，缓则必成。</p><p>○　问婚姻：因探听未确，迟缓可成。</p><p>○　问失物：日后可得。</p><p>○　问疾病：宜宽缓调养，可愈．</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>某县人来，请占志愿成否，筮得《晋》之《噬嗑》。</p><p>断曰：《晋》者进也，《晋》当初爻，是进步之初也，“摧如”者，欲进而有所摧折也，进者虽正，无如人不我信也。今足下占问志愿而得初爻，知足下品行端正，才具可用，但一时众情未孚，是以欲进又阻。初与四应，四不应初，反来阻初，料足下所托谋事之人，此人不能相助，反致相毁，故一时难望遂愿。宜到四爻曰“众允”之日，志愿可遂。一爻一月，大约在四月以后，大吉。其人尝携建议书，请谒某贵显，不能面达，反受警部之辱，得此占所云，大有感悟。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“愁如”，不悦之意，与“摧如”不同，愁者在我，摧者为人所阻。然二之所以“愁如”，实因初之见摧而来也。居中履正，故“贞吉”。“介福”，谓大福。“王母”，以二与五相应，五王位，《坤》阴，《坤》为妣，故曰“王母”；“王母”，即所谓太后也。二属《坤》，《坤》通《乾》，《乾》为“介福”。按《井》三曰王明受福，《既济》五曰“实受其福”，《井》三、《既济》五，皆得《乾》体，其福盖皆受之于《乾》也。二又互《艮》，《艮》为手，手持福以与二，二受之，故曰“受兹介福”。九家《易》云：“介福谓马与蕃庶之物也。”《象传》曰“以中正也”，谓其守此中正，不以无应而回其志，故终得受此大福也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下运非不佳，但所求多阻，中心未免忧结，能守正不改，终必亨通大利。</p><p>○　问战征：前番进攻，既遭摧折，今此再进，殊切愁惧，然能临事而惧，后必获吉。六二与六五相应，六五辰在卯，上值氐、房、心、尾，氐星前二大星主后妃，故取象王母，祷之，则有福。</p><p>○　问营商：因前贩之货，已被折耗，今兹未免怀愁，故曰“晋如愁如”。惟中正自守，至五爻乃曰“失得勿恤，往吉，无不利”，盖劝其不必忧愁，而自然获福也。</p><p>○　问功名：今虽忧愁，至五爻曰“往有庆”，盖二年之后，即可获吉。</p><p>○　问婚姻：吉，但目下不就，须待第三年可成。当有祖母为之作主。</p><p>○　问家宅：当迁居，与祖母同居共食，吉。</p><p>○　问失物：久后可得。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治五年，余随陆军大佐福原实氏，赴赞州谋筑兵营。时坐轮船中，福原氏曰：方今我国形势，前途未可知，请试一占。筮得《晋》之《未济》。</p><p>断曰：《晋》者进也，欲进而愁其见摧，是进而未能进也，故爻曰“晋如愁如”。六二以阴居阴，但得中正，与初为比，因初之摧，倍切忧思，可谓临事知惧，故得“贞吉”。今占我国时势得此爻，我国自维新以来，力图进取，以启文明，初时内为旧藩士意见不合所阻，外为泰西各国风教不同所困，下又为改革不便所扰，是以欲进而未能遽进。兹当二爻，二与五应，五属尊位，知当道大臣，蒙我皇上帝心简在，上下一心，固不敢畏难思退，惟是进步艰难，日切忧虑，此即爻辞之所谓“晋如愁如”是也。当日三条公以下诸位大臣，秉正谋国，不特受知于皇上，且为太后所信任也，此即爻辞所谓“受兹介福，于其王母”是也。就前后爻辞而详推之，初爻则属之前事，二爻则属之今日，二五相应，是即《彖》所称“康侯”者也。三爻则初之“罔孚”者，而众孚矣，得以上行无悔。四爻则恐有谗邪在位，如鼠之昼伏夜行，进退诡秘，意将窃弄政权，为宜戒也。五爻当君位，是明君在上，殷殷焉为诸臣劝驾。曰“失得勿恤，往吉，无不利”，盖指二之“愁如”者言，谓失得不足忧，往则“无不利”。“有庆”者，即受福之谓也。上爻居《离》之极，《离》上“王用出征”，故五爻亦用“伐邑”，谓再有摧我者，当以王师讨之，使不敢复阻我前进也。爻象一爻或当一年，或当十年，可以定数求之。统之《晋》者进也，继《大壮》而来，为宜柔顺上行，不宜刚健躁进，盖取《坤》之顺而在下，尤必取《离》之明而在上，君子自昭明德，胥是道也。武功必先文德，上爻之“伐邑”，知亦不得已而用之耳。我国明良交际，文武兼修，国富兵强，日进日盛，正万年有道之休也，岂不休哉！福原氏闻之，大为感服。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三居内卦之上，与四为比，刚阻于前，似宜有悔。“允”，信也，六三辰在亥，得《乾》，《乾》为信。三比近初二，又与初二同心并力，合之为三，三人成众，故“众允”。外卦为《离》，《离》取其明，所谓克明克允是也。“众允”则四不能摧，故“悔亡”。古今来为国谋事，要皆以众心之向背为成败者也，众心不顺，其事虽正，卒无成功。孟子所谓“多助之至，天下顺之”者，“众允”之义也。初之“罔孚”，未信也；三之“众允”，见信也。孔子所谓“信而后谏”，“信而后劳其民”，事上使下，道在是焉。《象传》曰“众允之，志上行也”，三与上应，志在上行，故能与众同信也。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：目下灾悔已去，大众悦服，故吉。</p><p>○　问营商：初时为众所摧，不能获利，今众情和睦，可以无咎，卖买皆利。</p><p>○　问战征：众志成城，战必胜，攻必克，上行无悔。</p><p>○　问功名：得众人推举乃成。</p><p>○　问家宅：主眷属和睦，吉。</p><p>○　问婚姻：两姓和谐，吉。</p><p>○　问讼事：得有第三人出而处理，两造允从，无悔。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>九州商人某来，请占购买某大会社物品成否，如何，筮得《晋》之《旅》。</p><p>断曰：卦体下顺上明，显见以明白无欺，柔顺得众为要。今占购卖物品，而得《晋》三爻，知其在初爻，己欲购卖，为人所摧折不成；二爻又欲卖之，为己多愁虑未定。兹当三爻，已见众心允洽，虽四爻为贪人，意欲从中取利，然因大众已允，亦不复阻止矣。准可购买，无悔。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四爻以阳居阴，不中不正，当上下四阴之中，上互《坎》，下互《艮》，《坎》为隐伏，《艮》为鼠，《坎》隐而伤明，《艮》止而伤顺，无其德而居其位，上承阴柔之主，窃弄威权，下抑众阴，使忠言不得上达，以隔绝上下之效者也。其贪戾之性，犹如鼫鼠，故曰“晋如鼫鼠”。自来奸臣得位，其性贪残，昼伏夜动，诡秘百端，窃威弄权，狡同鼫鼠，一旦明德当阳，察识奸邪，浑如硕鼫见猫，罔不捕灭，故曰“贞厉”。《象传》曰“不当位也”，谓斯不当居斯位，为窃位也。按；《解》之卦，以阴居阳象狐，《晋》之卦，以阳居阴象鼠，此卦互体《艮》，一阳在上，故称“鼫鼠”。狐性疑，在《解》当去其疑；鼠性贪，在《晋》当去其贪，取象各有所当。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：运有蹊跷，宜光明正大处之，若持首鼠两端之见，好为狡诈，必凶。</p><p>○　问战征：《晋·彖》曰“昼日三接”，或曰接即捷，言一昼间而得三捷。若疑而又贪，如鼠之昼伏夜动，则危。</p><p>○　问功名：爻曰“鼫鼠”，鼫鼠谓五技皆劣，是必不能得志也。</p><p>○　问营商：鼠性贪，贪无不败，防为同伙贪财致败。</p><p>○　问家宅：鼠为穴虫，善盗，宅多鼠，必主耗失。不利。</p><p>○　问疾病：《诗》云“鼠思泣血”，或有呕血之症；又曰“鼠忧以痒”，或有疥疮之疾，是亦可危。</p><p>○　问讼事：首鼠两端，是一却一前，一时不能决也。</p><p>○　问行人：昼伏夜行，必有事故，一时不归。</p><p>○　问失物：已入鼠穴，不得。</p><p>○　问婚姻：“鼠”为鼠窃，婚姻不正。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>商人某来，请占家政，筮得《晋》之《剥》。</p><p>断曰：卦体顺丽大明，柔进上行，足见主家者公明在上，一门柔顺和乐，有家业日进之象。今占得四爻，以阳居阴，位不得正；鼠为穴虫，昼伏夜动，贪而畏人，阴物也，四爻如之，故爻辞曰“晋如鼫鼠”。料足下家中必有鼠窃之徒，管理家务。如《诗》所咏“硕鼠硕鼠”，一则曰食苗，再则曰食谷，知盗食家产，为祸非浅，故曰“贞厉”，言家道虽贞亦厉也。足下其审之慎之！</p><p>子爵五条为荣君，将迁居西京，请占其吉凶如何？筮得《晋》之《剥》。</p><p>断曰：此卦内《坤》外《离》，为《晋》，《象》曰“明出地上”。出于东为明，日入于西为晦，卦德在明，是宜东不宜西也。今君将移居西京，辞爵归隐，占得《晋》四爻，按《晋》者为进，不宜于退，日出在东，不宜就西，象皆不合。四爻辞曰“《晋》如鼯鼠，贞厉”，谓首鼠两端，一前一却，正如君之进退疑虑，欲迁未决。“贞厉”者，谓退隐意非不正，恐后有危厉也。劝君不必迁移。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五爻为《晋》之主，高居尊位，柔而得中，惟与四相比昵，四遂得窃弄威权，隔绝二三，不得亲近，是以有悔。然五躬备明德，智足察奸，黜六四而任六二，昭明有融，上下交孚，故曰“悔亡”。“失得勿恤”者，谓五不自恃其明，委用六二，信任勿疑，计是非，不计得失，即有小失小得，不足庆也。“往”即“上行”，指康侯往朝于天子也。“吉，无不利”，指受介福于王母也，故《象传》曰“往有庆也。”庆，即“受兹介福”之谓也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：目下正当盛运，灾去福来，有得无失，大吉。</p><p>○　问战征：转败为胜，在此一战，奋勇前往，立见成功。</p><p>○　问营商：前此小失，今可大得，吉。</p><p>○　问功名：不必汲汲求名，可无意得之也。吉。</p><p>○　问家宅：日出于东，《离》位南方，此宅必朝东南。从前小有灾悔，今则屋运已转，吉无不利。</p><p>○　问婚姻：以九五为男家，六二为女家，两爻皆吉，大利。</p><p>○　问讼事：曰“悔亡”，谓灾害已去，罢讼则吉。</p><p>○　问失物：往寻必得。</p><p>○　问六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>华族某来，请占气运，筮得《晋》之《否》。</p><p>断曰：《晋》五爻为一卦之主，高明在上，且《坤》为邦为国，有屏藩一国之象。阁下占气运而得此爻，爻辞曰“悔亡，失得勿恤”，想阁下自废藩以来，从前或小有灾悔，今能柔顺上进，观光志正，是不以失得为忧也，故曰“悔亡”。“往”者，往朝也，上下交孚，故无往而不利也。闻阁下欲以每岁财产余利，教育藩士子弟，以为国家培植人材，至财产之得失，不复计虑，《彖》所称康侯者，必在阁下矣。他日恩赏下逮，车马藩庶，行有待焉，《象传》所谓“往有庆”者，此也。</p><p>明治三十一年，占内阁气运，筮得《晋》之《否》。</p><p>断曰：此卦明出地上，顺而丽夫大明，国家治体，骎骎上进之气运也。今占得五爻，五居君位，昭明有融，上下交孚，君明臣良，正在此时，然其间黜陟，不无些少纷扰。在内阁诸公，皆正色立朝，秉忠从事，不计劳辱，谓之“悔亡，失得勿恤，往吉，无不利也”。果哉！是年伊藤侯辞总理之爵，大隈板垣二伯入内阁，五月，山县侯升为总理。此间虽非无纷扰，国家益见进步，正合此占。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“角”者，阳而在上，喻威猛之义。上爻处《晋》之极，过刚失中，故曰“晋其角”，谓其知进不知退也。《离》为甲，为戎，《离》上“王用出征”，上爻体《离》，故亦曰“维用伐邑”。用者五，邑指四，奉命而伐之者，上也。四既有罪，声罪致讨，兵虽危事，吉而无咎也。然干羽可以格顽，玉帛可以戢争，不用文德，而用武功，亦未始非圣明之累也，故虽正亦吝，而《传》曰“道未光也”。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：目下好运将终，防有事故，然无大害。</p><p>○　问战征：只可近征国内，不可远伐海外。危而终吉。</p><p>○　问营商：于同业防有纷争，于事则危，于货则利，于情则吝，幸无咎也。</p><p>○　问功名：“晋，进也”，角在首上，有首选之象。功名成后，防有从戎之役。吉。</p><p>○　问家宅：居者于乡党中，有纷争之事，未免不安，然无大咎。</p><p>○　问婚姻：上与三相应，上与三，即为男女两姓，始有纷扰，终得和谐，故“悔亡”，与三同也。</p><p>○　问讼事：《雀角》之诗，刺讼也。罢讼则吉。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>友人某来曰：今有一会社，自创立以来，余所关虑。昨年总会，整顿社员，迄后事务不整，有株主之纷扰，其由社势之不振乎？抑由社员之不力乎？请一占其盛衰。筮得《晋》之《豫》。</p><p>断曰：《晋》者，明出地上，有社运日进日新之象。今占得上爻，为《晋》之极，是进无可进矣。物极必反，意者重有改革乎？“伐邑”者，即正其不正，可用前社员之练达者，以定会社之规则，庶几可得吉矣。事虽危殆，终无咎焉，从此社业复兴，不失其正。然自有识者观之，不免为之窃笑也，故曰“贞吝”。</p>',112)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
